META={'id':'g8-ma-kx-k','subj':'數學','name':'八上 數學 康軒 K卷','source':'康軒版 八年級數學（三）K卷（114上，依答案卷對答；解析為自編；僅收選擇題）'}

sec('第1回 1-1 乘法公式')
ch(r'如附圖，甲、乙為正方形，丙為長方形，請問邊長為 \((a-b)\) 的正方形面積與下列何者相等？',['(甲＋乙＋2 丙)的面積','(甲＋乙－2 丙)的面積',r'(甲\(^2\)＋乙\(^2\)＋2 丙)的面積',r'(甲\(^2\)＋乙\(^2\)－2 丙)的面積'],2,r'甲＝\(a^2\)，乙＝\(b^2\)，丙＝\(ab\)，\((a-b)^2=a^2-2ab+b^2\)＝甲＋乙－2 丙。',img=(1,400,155,520,285))
ch('下列算式何者正確？',[r'\((9-5)^2=9^2-2\times9\times5-5^2\)',r'\((5+7)^2=5^2+5\times7+7^2\)',r'\((18+6)(6-18)=18^2-6^2\)',r'\((10-3)(10+3)=10^2-3^2\)'],4,r'(A) 應為 \(+5^2\)；(B) 應為 \(2\times5\times7\)；(C) \((6+18)(6-18)=6^2-18^2\)；(D) 正確。')
ch(r'下列哪一個式子與 \((-a+b)^2\) 相等？',[r'\((a-b)^2\)',r'\((-a-b)^2\)',r'\(-(a+b)^2\)',r'\(-(a-b)^2\)'],1,r'\((-a+b)^2=[-(a-b)]^2=(a-b)^2\)。')
ch(r'計算 \(0.11\times25-0.89\times75-0.11\times75+0.89\times25\) 的值為何？',['5','－5','50','－50'],4,r'原式＝\(0.11\times(25-75)+0.89\times(25-75)=(0.11+0.89)\times(-50)=-50\)。')
ch(r'若 \(198^2=200^2-4k\)，則 \(k=\)？',['198','199','200','201'],2,r'\(198^2=(200-2)^2=200^2-800+4=200^2-796\)，\(4k=796\Rightarrow k=199\)。')
ch(r'設 \(a=97^2-22^2\)，則下列哪一個數不是 \(a\) 的因數？',['2','3','7','17'],1,r'\(a=(97+22)(97-22)=119\times75=7\times17\times3\times5^2\)，為奇數，故 2 不是 \(a\) 的因數。')
ch(r'計算 \(\dfrac{227^2-23^2}{227^2-2\times227\times23+23^2}\) 的值為何？',[r'\(\dfrac{102}{125}\)','1',r'\(\dfrac{125}{102}\)','2'],3,r'原式＝\(\dfrac{(227+23)(227-23)}{(227-23)^2}=\dfrac{250}{204}=\dfrac{125}{102}\)。')
ch(r'如附圖，有大、小兩個同心圓，大圓的半徑是 6.5，小圓的半徑是 3.5，則兩圓所圍成的鋪色區域面積為多少？（圓周率以 \(\pi\) 表示）',[r'\(6\pi\)',r'\(18\pi\)',r'\(30\pi\)',r'\(32\pi\)'],3,r'面積＝\(\pi(6.5^2-3.5^2)=\pi(6.5+3.5)(6.5-3.5)=30\pi\)。',img=(1,400,1040,520,1165))
ch(r'計算 \(\left(49+\dfrac{2}{3}\right)\times\left(60+\dfrac{1}{7}\right)\) 的結果，其個位數字為何？',['9','7','1','0'],2,r'原式＝\(49\times60+49\times\dfrac{1}{7}+\dfrac{2}{3}\times60+\dfrac{2}{3}\times\dfrac{1}{7}=2940+7+40+\dfrac{2}{21}=2987\dfrac{2}{21}\)，個位數字為 7。')
ch(r'已知 \(a=595^2+2\times595\times5+5^2\)，\(b=600^2-5^2\)，\(c=601\times599\)，則 \(a\)、\(b\)、\(c\) 三數的大小關係為何？',[r'\(a>b>c\)',r'\(c>a>b\)',r'\(a>c>b\)',r'\(b>a>c\)'],3,r'\(a=(595+5)^2=600^2\)，\(b=600^2-25\)，\(c=(600+1)(600-1)=600^2-1\)，故 \(a>c>b\)。')
endp()

sec('第2回 1-2 多項式與其加減運算')
ch(r'下列何者是 \(2x^4\) 的同類項？',[r'\(2x^3\)',r'\(2x\)',r'\(-x^4\)',r'\(4x^2\)'],3,r'同類項必須文字部分與次數都相同，故 \(-x^4\) 是 \(2x^4\) 的同類項。')
ch(r'下列有關多項式 \(-3x+7-2x^2\) 的敘述，何者正確？',[r'\(x\) 項的係數是 3','此多項式共有 2 項','此多項式是二次多項式','常數項是 －2'],3,r'\(x\) 項係數為 \(-3\)；共有 3 項；最高次為 2 次；常數項為 7，故選(C)。')
ch(r'下列何者是 \(x\) 的多項式？',[r'\(|x|-6\)',r'\(\dfrac{x}{2}-\dfrac{2}{x}\)',r'\(3x+8=29\)',r'\(-1-2x-3x^2\)'],4,r'(A) \(x\) 在絕對值內；(B) \(x\) 在分母；(C) 為方程式，皆不是多項式。')
ch(r'若多項式 \(ax^2+3x-5\) 與多項式 \(b+cx-4x^2\) 相等，則下列何者正確？',[r'\(a=4\)',r'\(b=-5\)',r'\(c=-3\)',r'\(a+b+c=12\)'],2,r'比較係數得 \(a=-4\)，\(c=3\)，\(b=-5\)，\(a+b+c=-6\)，故選(B)。')
ch(r'多項式 \(3x^3-x^2+7x-15\) 的各項係數總和為何？',['9','5','－4','－6'],4,r'\(3+(-1)+7+(-15)=-6\)。')
ch(r'計算 \((2x-x^2+5)-(3x^2-4-x)\) 所得的結果為多項式 \(A\)，則 \(A\) 的 \(x\) 項係數為何？',['－3','－1','1','3'],4,r'原式＝\(2x-x^2+5-3x^2+4+x=-4x^2+3x+9\)，\(x\) 項係數為 3。')
ch(r'已知 \(A\)、\(B\) 皆為二次多項式，則多項式 \(A+B\) 的次數不可能為多少次？',['3','2','1','0'],1,r'兩個二次多項式相加，次數最多為 2 次（二次項可能相消而變成一次、零次），不可能為 3 次。')
ch(r'化簡 \((8x^2+5x-6)+(ax^2-6x+b)\) 的結果，得 \(x^2\) 項的係數為 5，常數項為 2，則 \(a+b=\)？',['1','5','9','13'],2,r'\(8+a=5\Rightarrow a=-3\)；\(-6+b=2\Rightarrow b=8\)，\(a+b=5\)。')
ch(r'附圖為一個三角形，三邊長分別為 \(5x^2-4\)、\(6x-4\)、\(2x^2+3x-5\)，則其周長為何？',[r'\(7x^2+9x-13\)',r'\(13x^2-5x-5\)',r'\(7x^2+6x-9\)',r'\(13x^2+3x-13\)'],1,r'周長＝\((5x^2-4)+(6x-4)+(2x^2+3x-5)=7x^2+9x-13\)。',img=(2,390,1005,520,1095))
ch(r'【素養】元元手上拿著 \(7-5x\) 與 \(2x+x^2\) 兩張卡片，小風說：「把你手上的兩式相加後，再減去我手上的多項式，結果為 \(-x^3-x^2-3x+8\)。」請問小風手上拿的多項式為何？',[r'\(x^3+2x^2-1\)',r'\(x^3+2x^2+1\)',r'\(x^3-2x^2-1\)',r'\(x^3-2x^2+1\)'],1,r'兩式相加得 \(x^2-3x+7\)，小風的多項式＝\((x^2-3x+7)-(-x^3-x^2-3x+8)=x^3+2x^2-1\)。',img=(2,120,1225,520,1338))
endp()

sec('第3回 1-3 多項式的乘除運算')
ch('關於多項式的運算，下列何者正確？',[r'\((-x)\cdot(-x)=-x^2\)',r'\(x\cdot x-x=x\)',r'\((-x)\div x+x=x-1\)',r'\((x^2+x)\div x=x\)'],3,r'(A) \(x^2\)；(B) \(x^2-x\)；(C) \(-1+x=x-1\)，正確；(D) \(x+1\)。')
ch(r'將 \(3x\) 乘以下列哪一個多項式後會得到 \(-15x^4\)？',[r'\(-5x^3\)',r'\(-5x^4\)',r'\(5x^3\)',r'\(5x^4\)'],1,r'\(-15x^4\div3x=-5x^3\)。')
ch(r'已知 \((13x-7)(-x+9)=ax^2+bx-63\)，則下列何者錯誤？',[r'\(a=-13\)',r'\(b=89\)',r'\(ab<0\)',r'\(a+b>0\)'],2,r'\((13x-7)(-x+9)=-13x^2+117x+7x-63=-13x^2+124x-63\)，\(a=-13\)，\(b=124\)，故(B)錯誤。')
ch(r'多項式 \(5x^2-10x\) 可被下列何者整除？',[r'\(x-1\)',r'\(x-2\)',r'\(x-3\)',r'\(x-4\)'],2,r'\(5x^2-10x=5x(x-2)\)，可被 \(x-2\) 整除。')
ch(r'下列何者不可能為多項式 \(A\) 除以 \(-x^2+x\) 所得的餘式？',['0','1000',r'\(3x-2\)',r'\(2x^2\)'],4,r'除式為二次，餘式必為 0 或次數小於 2 的多項式，故不可能是 \(2x^2\)。')
ch(r'已知多項式 \(A=2x^2+1\)，\(B=5x-13\)，\(C=x+4\)，則 \((A+B)\div C=\)？',[r'\(2x-3\)',r'\(2x+3\)',r'\(2x-5\)',r'\(2x+5\)'],1,r'\(A+B=2x^2+5x-12=(x+4)(2x-3)\)，故 \((A+B)\div C=2x-3\)。')
ch(r'已知 \(A\) 為 \(x\) 的一次多項式，\(B\) 為 \(x\) 的二次多項式，則 \(A\times B\) 為 \(x\) 的幾次多項式？',['四','三','二','一'],2,r'\(1+2=3\)，為三次多項式。')
ch(r'已知一正三角形的面積為 \(2x^2-9x+10\)，高為 \(x-2\)，則此正三角形的周長為何？',[r'\(2x-5\)',r'\(4x-10\)',r'\(6x-15\)',r'\(12x-30\)'],4,r'邊長＝\(2(2x^2-9x+10)\div(x-2)=2(2x-5)=4x-10\)，周長＝\(3(4x-10)=12x-30\)。')
ch(r'計算 \((3x-1)(4x+7)-(6x^2+23x-18)\div(2x+9)\) 的結果，其常數項為何？',['9','5','－5','－9'],3,r'\((3x-1)(4x+7)\) 的常數項為 \(-7\)；\((6x^2+23x-18)\div(2x+9)=3x-2\)，常數項為 \(-2\)，所求＝\(-7-(-2)=-5\)。')
ch(r'已知 \(3x^2-14x+10\) 除以另一個多項式 \(A\) 後，得到的商式為 \(3x-2\)，餘式為 2，則多項式 \(A=\)？',[r'\(x-4\)',r'\(x+4\)',r'\(x-7\)',r'\(x+7\)'],1,r'\(A=(3x^2-14x+10-2)\div(3x-2)=(3x^2-14x+8)\div(3x-2)=x-4\)。')
endp()

sec('第4回 2-1 平方根與近似值')
ch('將 4 個圖(一)的等腰直角三角形（兩股長皆為 3）拼成如圖(二)的正方形，則此正方形的邊長為何？',['3',r'\(\sqrt{18}\)','6','12'],2,r'正方形面積＝\(4\times\dfrac{1}{2}\times3\times3=18\)，邊長＝\(\sqrt{18}\)。',img=(4,320,150,490,265))
ch('關於平方根的敘述，下列何者正確？',[r'若 \(a^2=b\)，則 \(b\) 為 \(a\) 的平方根','一數的平方根必有兩個，且互為相反數',r'因為 \(7^2=49\)、\((-7)^2=49\)，所以 \(\pm7\) 為 49 的平方根','0 沒有平方根'],3,r'(A) 應為 \(a\) 是 \(b\) 的平方根；(B) 0 只有一個平方根，負數沒有平方根；(D) 0 的平方根為 0。')
ch(r'欲使 \(\sqrt{2x-5}\) 是有意義的，則 \(x\) 不可能為下列何者？',['2','3','4','5'],1,r'需 \(2x-5\geq0\Rightarrow x\geq2.5\)，故 \(x\) 不可能為 2。')
ch('下列各數的大小關係何者錯誤？',[r'\(\sqrt{110}<11\)',r'\(\sqrt{100}=10\)',r'\(\sqrt{90}>9\)',r'\(\sqrt{80}<8\)'],4,r'\(8=\sqrt{64}<\sqrt{80}\)，故(D)錯誤。')
ch(r'數線上有 \(A(\sqrt{4})\)、\(B(\sqrt{7})\)、\(C(\sqrt{11})\)、\(D(\sqrt{18})\)、\(E(\sqrt{23})\)、\(F(\sqrt{28})\)、\(G(\sqrt{37})\) 七個點，則在 3 和 5 之間的點有幾個？',['1','3','5','7'],2,r'\(3=\sqrt{9}\)，\(5=\sqrt{25}\)，介於其間的有 \(\sqrt{11}\)、\(\sqrt{18}\)、\(\sqrt{23}\)，共 3 個。')
ch('請問 450 的正平方根介於下列哪兩個連續整數之間？',['21、22','22、23','23、24','24、25'],1,r'\(21^2=441<450<484=22^2\)。')
ch(r'若 \(\sqrt{\dfrac{x-1}{2}}=3\)，則 \(x=\)？',['5','7','11','19'],4,r'\(\dfrac{x-1}{2}=9\Rightarrow x=19\)。')
ch(r'附表為 5 個數及其平方後所得到的值（\(8^2=64\)、\(9^2=81\)、\(10^2=100\)、\(11^2=121\)、\(12^2=144\)）。利用此表估算 \(\sqrt{130}\) 的整數部分為何？',['11','12','30','40'],1,r'\(121<130<144\Rightarrow11<\sqrt{130}<12\)，整數部分為 11。',img=(4,292,1068,488,1118))
ch('下列哪一選項的值為整數？',[r'\(\sqrt{2\times3\times12}\)',r'\(\sqrt{2\times4\times8}\)',r'\(\sqrt{2\times5\times15}\)',r'\(\sqrt{3\times5\times10}\)'],2,r'\(\sqrt{2\times4\times8}=\sqrt{64}=8\)。')
ch(r'若 \(a\) 為 25 的平方根，\(b\) 為 49 的平方根，則 \(a+b\) 之值可能為下列哪一個選項？',['－14','－10','－2','5'],3,r'\(a=\pm5\)，\(b=\pm7\)，\(a+b\) 可能為 12、2、\(-2\)、\(-12\)，故選(C)。')
endp()

sec('第5回 複習一（1-1～2-1）')
ch(r'如附圖，甲、乙、丙、丁四個長方形中，哪一個的面積不是 \(6x\)？',['甲','乙','丙','丁'],3,r'甲＝\(6x\times1=6x\)；乙＝\(3x\times2=6x\)；丁＝\(2x\times3=6x\)；丙的寬為 \(6x-3x-2x=x\)，面積＝\(x\times6x=6x^2\)。',img=(5,395,145,525,285))
ch('下列各式中，哪一個是升冪排列？',[r'\(x+2x^3+3x^2+4\)',r'\(-5+8x^3\)',r'\(4x^3+3x^2+2x+1\)',r'\(-2x+3-4x^2\)'],2,r'升冪排列是依次數由低至高排列，\(-5+8x^3\) 符合。')
ch(r'已知 \(a>0\)、\(b>0\)，若 \(207^2=200^2+2\times200\times a+b^2\)，則 \(a+b\) 的值為何？',['7','14','28','42'],2,r'\(207^2=(200+7)^2=200^2+2\times200\times7+7^2\)，\(a=7\)，\(b=7\)，\(a+b=14\)。')
ch(r'將 \((-3x+4x^2-5)\) 減去 \((-3x^2+4x-5)\) 的結果為幾次多項式？',['零次','一次','二次','四次'],3,r'原式＝\(-3x+4x^2-5+3x^2-4x+5=7x^2-7x\)，為二次多項式。')
ch(r'若 \(-7\) 是 \(3x+1\) 的一個平方根，則 \(x=\)？',['16','17','18','19'],1,r'\(3x+1=(-7)^2=49\Rightarrow x=16\)。')
ch('關於多項式乘法的運算，下列哪一個選項是正確的？',[r'\((13x-1)^2=169x^2-13x+1\)',r'\((4x+3)^2=16x^2+9\)',r'\((5x-1)(2x-3)=10x^2+3\)',r'\((3x-7)(3x+7)=9x^2-49\)'],4,r'(A) 中間項應為 \(-26x\)；(B) 缺 \(24x\)；(C) \(10x^2-17x+3\)；(D) 正確。')
ch(r'請問 \(\sqrt{330}\) 的整數部分為何？',['17','18','19','330'],2,r'\(18^2=324<330<361=19^2\)，整數部分為 18。')
ch(r'已知 \(A\) 為二次多項式，\(B\) 為一次多項式，則下列何者正確？',[r'\(A+B\) 的結果為三次多項式',r'\(A-B\) 的結果為一次多項式',r'\(A\times B\) 的結果為二次多項式',r'\(A\div B\) 的商式為一次多項式'],4,r'\(A+B\)、\(A-B\) 皆為二次多項式；\(A\times B\) 為三次多項式；\(A\div B\) 的商式為一次多項式。')
ch('琪琪將一張正方形色紙剪下一個小正方形，如附圖所示（大正方形邊長 17，剪下的小正方形邊長 13）。根據圖中的數據，則剩餘的色紙面積為何？',['120','136','144','150'],1,r'所求＝\(17^2-13^2=(17+13)(17-13)=120\)。',img=(5,380,1140,520,1295))
ch(r'若多項式 \(2x^2+ax-15\) 能被 \(2x-3\) 整除，則 \(a\) 之值為何？',['－13','－7','7','13'],3,r'\(2x^2+ax-15=(2x-3)(x+5)=2x^2+7x-15\)，故 \(a=7\)。')
endp()

sec('第6回 2-2 根式的運算')
ch(r'下列哪一個算式的結果與 \(\sqrt{2}\div\sqrt{\dfrac{1}{3}}\times\sqrt{5}\) 相等？',[r'\(\sqrt{2}\div\sqrt{5}\times\sqrt{\dfrac{1}{3}}\)',r'\(\sqrt{\dfrac{1}{3}}\times\sqrt{5}\div\sqrt{2}\)',r'\(\sqrt{2}\times\sqrt{3}\div\sqrt{5}\)',r'\(\sqrt{2}\times\sqrt{3}\times\sqrt{5}\)'],4,r'除以 \(\sqrt{\dfrac{1}{3}}\) 等於乘以 \(\sqrt{3}\)，原式＝\(\sqrt{2}\times\sqrt{3}\times\sqrt{5}\)。')
ch('下列哪一組選項化簡後不是同類方根？',[r'\(\sqrt{24}\) 和 \(\sqrt{54}\)',r'\(\sqrt{32}\) 和 \(\sqrt{72}\)',r'\(\sqrt{44}\) 和 \(\sqrt{484}\)',r'\(\sqrt{300}\) 和 \(\sqrt{75}\)'],3,r'(A) \(2\sqrt{6}\)、\(3\sqrt{6}\)；(B) \(4\sqrt{2}\)、\(6\sqrt{2}\)；(C) \(2\sqrt{11}\)、22，不是同類方根；(D) \(10\sqrt{3}\)、\(5\sqrt{3}\)。')
ch(r'若 \(\sqrt{360}=a\sqrt{40}=6\sqrt{b}\)，則 \(a-b\) 之值為何？',['－7','－5','－3','－1'],1,r'\(\sqrt{360}=\sqrt{9\times40}=3\sqrt{40}=6\sqrt{10}\)，\(a=3\)，\(b=10\)，\(a-b=-7\)。')
ch(r'下列哪一個數的 3 倍會等於 \(\sqrt{12}\)？',[r'\(2\sqrt{3}\)',r'\(\dfrac{2}{\sqrt{3}}\)',r'\(\dfrac{4}{\sqrt{3}}\)',r'\(\sqrt{4}\)'],2,r'\(\sqrt{12}\div3=\dfrac{2\sqrt{3}}{3}=\dfrac{2}{\sqrt{3}}\)。')
ch(r'若要將 \(\sqrt{\dfrac{5}{24}}\) 化為最簡根式，可將分子和分母同時乘以下列哪一個數？',[r'\(\sqrt{2}\)',r'\(\sqrt{3}\)',r'\(\sqrt{5}\)',r'\(\sqrt{6}\)'],4,r'\(\sqrt{\dfrac{5}{24}}=\dfrac{\sqrt{5}}{2\sqrt{6}}=\dfrac{\sqrt{5}\times\sqrt{6}}{2\sqrt{6}\times\sqrt{6}}=\dfrac{\sqrt{30}}{12}\)。')
ch(r'若 \(\sqrt{20}+\sqrt{45}+\sqrt{80}=m\times\sqrt{5}\)，則 \(m=\)？',['8','9','10','11'],2,r'\(2\sqrt{5}+3\sqrt{5}+4\sqrt{5}=9\sqrt{5}\)，\(m=9\)。')
ch('下列各式的計算結果何者正確？',[r'\((3+\sqrt{10})(3-\sqrt{10})=1\)',r'\((2-\sqrt{5})^2=-1-4\sqrt{5}\)',r'\((1+\sqrt{2})^2=3+2\sqrt{2}\)',r'\((\sqrt{3}+2)(2-\sqrt{3})=-1\)'],3,r'(A) \(9-10=-1\)；(B) \(9-4\sqrt{5}\)；(C) \(1+2\sqrt{2}+2=3+2\sqrt{2}\)，正確；(D) \(4-3=1\)。')
ch('下列各選項中所表示的數，哪一個不是整數？',[r'\(\sqrt{98}-\sqrt{2}\)',r'\(\sqrt{98}\div\sqrt{2}\)',r'\(\sqrt{196}+\sqrt{4}\)',r'\(\sqrt{196}\times\sqrt{4}\)'],1,r'(A) \(7\sqrt{2}-\sqrt{2}=6\sqrt{2}\)，不是整數；(B) 7；(C) 16；(D) 28。')
ch(r'有一正方形的周長為 \(\sqrt{192}\) 公分，則此正方形的面積為多少平方公分？',['9','12','15','18'],2,r'邊長＝\(\sqrt{192}\div4=8\sqrt{3}\div4=2\sqrt{3}\)，面積＝\((2\sqrt{3})^2=12\)。')
ch(r'已知 \(a\)、\(b\) 互為倒數，且 \(a=3-\sqrt{5}\)，則 \(b=\)？',[r'\(3+\sqrt{5}\)',r'\(\dfrac{3+\sqrt{5}}{2}\)',r'\(\dfrac{3+\sqrt{5}}{4}\)',r'\(\dfrac{3+\sqrt{5}}{8}\)'],3,r'\(b=\dfrac{1}{3-\sqrt{5}}=\dfrac{3+\sqrt{5}}{9-5}=\dfrac{3+\sqrt{5}}{4}\)。')
endp()

sec('第7回 2-3 畢氏定理')
ch(r'\(\triangle ABC\) 中，\(\angle A=90^\circ\)，則下列何者正確？',[r'\(\overline{AB}^2+\overline{AC}^2=\overline{BC}^2\)',r'\(\overline{BC}^2+\overline{AC}^2=\overline{AB}^2\)',r'\(\overline{AB}^2+\overline{BC}^2=\overline{AC}^2\)',r'\(\overline{AB}=\overline{BC}=\overline{AC}\)'],1,r'\(\angle A=90^\circ\)，斜邊為 \(\overline{BC}\)，故 \(\overline{AB}^2+\overline{AC}^2=\overline{BC}^2\)。')
ch(r'分別以某直角三角形的三邊長為邊長作三個正方形，其面積由小到大為 4、6、\(a\)，則 \(a\) 值為何？',['8','10','12','24'],2,r'以斜邊為邊長的正方形面積＝另兩個正方形面積和，\(a=4+6=10\)。')
ch(r'坐標平面上有 \(A(3,-2)\)、\(B(-5,1)\) 兩點，則 \(\overline{AB}=\)？',['3',r'\(\sqrt{13}\)',r'\(\sqrt{73}\)','11'],3,r'\(\overline{AB}=\sqrt{(3+5)^2+(-2-1)^2}=\sqrt{64+9}=\sqrt{73}\)。')
ch('已知直角三角形的一邊長為 15，則下列哪一組數據不可能為此三角形的另外兩邊長？',['9、12','8、17','22、23',r'\(5\sqrt{7}\)、20'],3,r'(A) \(9^2+12^2=15^2\)；(B) \(8^2+15^2=17^2\)；(D) \((5\sqrt{7})^2+15^2=175+225=400=20^2\)；(C) \(15^2+22^2\neq23^2\)，\(15^2+23^2\neq22^2\)。')
ch(r'已知正三角形 \(ABC\) 的邊長為 8，則其面積為何？',[r'\(12\sqrt{3}\)',r'\(16\sqrt{3}\)',r'\(20\sqrt{3}\)',r'\(24\sqrt{3}\)'],2,r'高＝\(\sqrt{8^2-4^2}=4\sqrt{3}\)，面積＝\(\dfrac{1}{2}\times8\times4\sqrt{3}=16\sqrt{3}\)。')
ch(r'如附圖，\(\triangle ABC\) 中，\(\overline{AD}\perp\overline{BC}\) 於 \(D\) 點。若 \(\overline{AB}=25\)，\(\overline{BD}=20\)，\(\overline{AC}=17\)，則 \(\triangle ABC\) 的周長為何？',['64','66','68','70'],4,r'\(\overline{AD}=\sqrt{25^2-20^2}=15\)，\(\overline{DC}=\sqrt{17^2-15^2}=8\)，周長＝\(25+17+(20+8)=70\)。',img=(7,345,585,490,680))
ch(r'附圖的方格紙上有線段 \(\overline{AB}\)、\(\overline{CD}\)、\(\overline{EF}\)。設每一方格的邊長均為 1，則 \(\overline{AB}\)、\(\overline{CD}\)、\(\overline{EF}\) 三線段長度的大小關係為何？',[r'\(\overline{AB}>\overline{CD}>\overline{EF}\)',r'\(\overline{AB}>\overline{EF}>\overline{CD}\)',r'\(\overline{CD}>\overline{AB}>\overline{EF}\)',r'\(\overline{CD}>\overline{EF}>\overline{AB}\)'],4,r'\(\overline{AB}=\sqrt{1^2+2^2}=\sqrt{5}\)，\(\overline{CD}=\sqrt{3^2+1^2}=\sqrt{10}\)，\(\overline{EF}=\sqrt{2^2+2^2}=\sqrt{8}\)，故 \(\overline{CD}>\overline{EF}>\overline{AB}\)。',img=(7,370,730,505,825))
ch(r'如附圖，將四個相同大小的直角三角形與一個小正方形拼成一個大正方形 \(ABCD\)。若正方形 \(ABCD\) 的周長為 52，且 \(\overline{AE}=5\)，則正方形 \(EFGH\) 的面積為何？',['49','64','81','100'],1,r'大正方形邊長＝13，直角三角形斜邊 13、一股 5，另一股＝12，\(EFGH\) 面積＝\(13^2-4\times\dfrac{1}{2}\times5\times12=169-120=49\)。',img=(7,398,900,495,1010))
ch('已知甲、乙兩車自停車場離開後，甲車朝東方以時速 60 公里的速度前進，乙車朝北方以時速 80 公里的速度前進，則 90 分鐘後甲、乙兩車的最短距離為多少公里？',['100','120','140','150'],4,r'90 分鐘＝1.5 小時，甲行 90 公里，乙行 120 公里，距離＝\(\sqrt{90^2+120^2}=150\)（公里）。')
ch(r'如附圖，\(O\) 為數線上的原點，\(A\) 點坐標為 1。若 \(\triangle OAB\)、\(\triangle OBC\)、\(\triangle OCD\) 都是直角三角形，且 \(\overline{AB}=\overline{BC}=\overline{CD}=1\)，\(\overline{OD}=\overline{OE}\)，則 \(E\) 點坐標為何？',[r'\(-\sqrt{3}\)','－2',r'\(-\sqrt{6}\)','－3'],2,r'\(\overline{OB}=\sqrt{2}\)，\(\overline{OC}=\sqrt{3}\)，\(\overline{OD}=\sqrt{4}=2\)，\(E\) 在原點左側，坐標為 \(-2\)。',img=(7,310,1240,495,1350))
endp()

sec('第8回 3-1 利用提公因式與乘法公式做因式分解')
ch(r'已知 \(3x^2-10x+8\) 可因式分解成 \((3x-4)(x-2)\)，則下列何者不是 \(3x^2-10x+8\) 的因式？',[r'\(3x-4\)',r'\(4-2x\)',r'\(2+x\)',r'\(\dfrac{3}{5}x-\dfrac{4}{5}\)'],3,r'\(4-2x=-2(x-2)\)、\(\dfrac{3}{5}x-\dfrac{4}{5}=\dfrac{1}{5}(3x-4)\) 皆為其因式；\(2+x\) 不是。')
ch(r'下列何者為 \(2x^2+7x\) 的因式？',[r'\(x-7\)',r'\(x+7\)',r'\(2x-7\)',r'\(2x+7\)'],4,r'\(2x^2+7x=x(2x+7)\)。')
ch(r'因式分解 \(4x^2-9\) 的結果為何？',[r'\((4x+9)(4x-9)\)',r'\((4x+3)(4x-3)\)',r'\((2x+9)(2x-9)\)',r'\((2x+3)(2x-3)\)'],4,r'\(4x^2-9=(2x)^2-3^2=(2x+3)(2x-3)\)。')
ch(r'若 \(8x^2-24x+18\) 可因式分解成 \(a(2x+b)^2\)，則下列何者正確？',[r'\(a=8\)',r'\(b=3\)',r'\(a+b=-1\)',r'\(a<b\)'],3,r'\(8x^2-24x+18=2(4x^2-12x+9)=2(2x-3)^2\)，\(a=2\)，\(b=-3\)，\(a+b=-1\)。')
ch(r'利用提公因式將 \(2(x+3)-x(x+3)\) 因式分解後，判斷下列哪一個選項不是此多項式的因式？',[r'\(x+3\)',r'\(x-3\)',r'\(x-2\)',r'\(2-x\)'],2,r'原式＝\((x+3)(2-x)=-(x+3)(x-2)\)，\(x-3\) 不是其因式。')
ch('下列各選項中的因式分解何者正確？',[r'\(9a^2+4b^2=(3a+2b)(3a-2b)\)',r'\(a^2-\dfrac{2}{5}a+\dfrac{1}{25}=\left(a+\dfrac{1}{5}\right)^2\)',r'\(9a^2+6a+1=(3a+1)^2\)',r'\(5a^2-20b^2=5(a+4b)(a-4b)\)'],3,r'(A) 平方和無法用平方差公式；(B) 應為 \(\left(a-\dfrac{1}{5}\right)^2\)；(D) 應為 \(5(a+2b)(a-2b)\)。')
ch(r'請問 \(x-4\) 是下列哪一個式子的因式？',[r'\((x^2+1)-4(x+1)\)',r'\((x^2+x)-4(x+1)\)',r'\((x^2-1)+4(x-1)\)',r'\((x^2-x)+4(x-1)\)'],2,r'\((x^2+x)-4(x+1)=x(x+1)-4(x+1)=(x+1)(x-4)\)。')
ch(r'若 \(A=x^2+x\)，\(B=x^2-1\)，則下列何者為 \(A\)、\(B\) 的公因式？',[r'\(x\)',r'\(x^2\)',r'\(x-1\)',r'\(x+1\)'],4,r'\(A=x(x+1)\)，\(B=(x+1)(x-1)\)，公因式為 \(x+1\)。')
ch(r'附圖是莎莎、小介兩人各做一題因式分解的過程：莎莎：\(x(2x-5)+x=x[(2x-5)+0]=x(2x-5)\)；小介：\(4(2x-1)-(1-2x)^2=4(2x-1)+(2x-1)^2=(2x-1)[4+(2x-1)]=(2x-1)(2x+3)\)。則關於兩人的作法，下列判斷何者正確？',['莎莎、小介皆錯誤','莎莎、小介皆正確','莎莎正確，小介錯誤','莎莎錯誤，小介正確'],1,r'莎莎：應為 \(x[(2x-5)+1]=x(2x-4)\)；小介：\((1-2x)^2=(2x-1)^2\)，應為 \(4(2x-1)-(2x-1)^2=(2x-1)(5-2x)\)，兩人皆錯誤。',img=(8,100,1095,480,1235))
ch(r'下列何者是 \((5x-3)^2-10(5x-3)+25\) 的因式？',[r'\(5x-8\)',r'\(5x-3\)',r'\(5x+3\)',r'\(5x+8\)'],1,r'原式＝\([(5x-3)-5]^2=(5x-8)^2\)。')
endp()

sec('第9回 3-2 利用十字交乘法做因式分解')
ch(r'附圖是阿理利用十字交乘法將 \(2x^2-7x+6\) 因式分解的過程（第一列 \(2x\) 配 \(\boxed{A}\)、第二列 \(x\) 配 \(\boxed{B}\)，交叉相乘得 \(\boxed{C}x+(-4x)\)），則 \(A+B+C=\)？',['－8','0','4','8'],1,r'\(2x^2-7x+6=(2x-3)(x-2)\)，\(A=-3\)，\(B=-2\)，交叉相乘 \(x\cdot(-3)=-3x\)、\(2x\cdot(-2)=-4x\)，\(C=-3\)，\(A+B+C=-8\)。',img=(9,400,150,520,215))
ch(r'下列哪一個式子無法分解成兩個 \(x\) 的一次式相乘？',[r'\(x^2+3x\)',r'\(-5x^2\)',r'\(x^2+x+2\)',r'\(2x^2-x-1\)'],3,r'(A) \(x(x+3)\)；(B) \((-5x)\cdot x\)；(D) \((2x+1)(x-1)\)；(C) 找不到兩整數積為 2、和為 1，無法分解。')
ch(r'若 \(x^2+3x-28\) 可因式分解成 \((x+a)(x+b)\)，其中 \(a>b\)，則 \(a-b\) 的值為何？',['11','－11','12','－12'],1,r'\(x^2+3x-28=(x+7)(x-4)\)，\(a=7\)，\(b=-4\)，\(a-b=11\)。')
ch(r'下列何者不是 \(2x-3\) 的倍式？',[r'\(2x^2-13x+15\)',r'\(4x^2+4x-3\)',r'\(6x^2-5x-6\)',r'\(8x^2-18x+9\)'],2,r'(A) \((2x-3)(x-5)\)；(B) \((2x+3)(2x-1)\)，不含 \(2x-3\)；(C) \((2x-3)(3x+2)\)；(D) \((2x-3)(4x-3)\)。')
ch(r'下列何者為 \((6x^2-3x)-2(7x-5)\) 的因式？',[r'\(x+2\)',r'\(x-2\)',r'\(3x-1\)',r'\(6x+5\)'],2,r'原式＝\(6x^2-17x+10=(6x-5)(x-2)\)。')
ch(r'已知兩多項式 \(M=2x^2-3x+1\) 與 \(N=4x^2+4x-3\)，則下列何者為 \(M\) 與 \(N\) 的公因式？',[r'\(x+1\)',r'\(x-1\)',r'\(2x+3\)',r'\(2x-1\)'],4,r'\(M=(2x-1)(x-1)\)，\(N=(2x-1)(2x+3)\)，公因式為 \(2x-1\)。')
ch(r'因式分解 \(-12x^2-11x+5\) 的結果為何？',[r'\(-(3x+1)(4x+5)\)',r'\(-(3x+1)(4x-5)\)',r'\(-(3x-1)(4x+5)\)',r'\(-(3x-1)(4x-5)\)'],3,r'\(-12x^2-11x+5=-(12x^2+11x-5)=-(3x-1)(4x+5)\)。')
ch(r'附圖為一多項式因式分解的過程：\(x^2+(2-4)x-\)甲\(=(x+2)(x+\)乙\()\)，甲、乙兩處應分別填入哪一數字？',['甲：6，乙：－4','甲：6，乙：4','甲：8，乙：－4','甲：8，乙：4'],3,r'\((x+2)(x+\)乙\()=x^2+(2+\)乙\()x+2\times\)乙，比較得乙＝\(-4\)，\(-\)甲＝\(2\times(-4)=-8\)，甲＝8。',img=(9,345,915,520,985))
ch(r'已知 \(91x^2+12x-55\) 可因式分解成 \((7x-5)(13x+11)\)，則 \(55x^2-12x-91\) 可因式分解為何？',[r'\((5x+7)(11x-13)\)',r'\((5x-7)(11x-13)\)',r'\((5x+7)(11x+13)\)',r'\((5x-7)(11x+13)\)'],4,r'\((5x-7)(11x+13)=55x^2+65x-77x-91=55x^2-12x-91\)。')
ch(r'附圖是甲、乙、丙三款磁磚（甲：邊長 \(x\) 的正方形；乙：長 \(x\)、寬 1 的長方形；丙：邊長 1 的正方形），若阿杰用 6 個甲磁磚、11 個乙磁磚、4 個丙磁磚恰好可以鋪滿房間的長方形地板，則下列何者可能為地板的邊長？',[r'\(3x-4\)',r'\(3x+2\)',r'\(2x-1\)',r'\(2x+1\)'],4,r'地板面積＝\(6x^2+11x+4=(2x+1)(3x+4)\)，故邊長可能為 \(2x+1\)。',img=(9,315,1210,520,1335))
endp()

sec('第10回 複習二（2-2～3-2）')
ch('已知下列鋪色圖形都是正方形，且圖中的數為各正方形的面積，則哪一個字母所代表的正方形面積不是 81？',['A','B','C','D'],2,r'(A) \(36+45=81\)；(B) \(160-80=80\)；(C) \(225-144=81\)；(D) \(1681-1600=81\)，故選(B)。',img=(10,100,235,520,470))
ch(r'計算 \(\sqrt{72}\div\sqrt{\dfrac{2}{5}}\times\sqrt{50}=\)？',[r'\(12\sqrt{3}\)',r'\(12\sqrt{10}\)',r'\(18\sqrt{2}\)',r'\(30\sqrt{10}\)'],4,r'原式＝\(\sqrt{72\times\dfrac{5}{2}\times50}=\sqrt{9000}=30\sqrt{10}\)。')
ch(r'若多項式 \(x^2-4x-45\) 可因式分解成 \((x+a)(x+b)\)，則 \(a\times b\) 之值為何？',['－45','－4','4','45'],1,r'\(x^2-4x-45=(x-9)(x+5)\)，\(ab=-45\)。')
ch(r'若 \(x^2-12x+36=x^2-2\cdot x\cdot a+b^2=(x-c)^2\)，且 \(a\)、\(b\)、\(c\) 均為正數，則下列何者正確？',[r'\(a-b+c=0\)',r'\(a=b=c\)',r'\(b=ac\)',r'\(a^2-bc>0\)'],2,r'\(x^2-12x+36=x^2-2\cdot x\cdot6+6^2=(x-6)^2\)，\(a=b=c=6\)。')
ch(r'已知 \(A=2x^2-5x-3\)，\(B=(x^2-4)-x-2\)，則 \(A\)、\(B\) 的公因式為何？',[r'\(x-1\)',r'\(x+1\)',r'\(x-3\)',r'\(x+3\)'],3,r'\(A=(2x+1)(x-3)\)；\(B=(x+2)(x-2)-(x+2)=(x+2)(x-3)\)，公因式為 \(x-3\)。')
ch(r'有一長方形的面積為 \(3x^2+10x-8\)，則下列何者可能為此長方形的邊長？',[r'\(\dfrac{x}{2}-\dfrac{1}{3}\)',r'\(\dfrac{x}{2}-2\)',r'\(x+2\)',r'\(3x+4\)'],1,r'\(3x^2+10x-8=(3x-2)(x+4)=6\left(\dfrac{x}{2}-\dfrac{1}{3}\right)(x+4)\)，故 \(\dfrac{x}{2}-\dfrac{1}{3}\) 可能為邊長。')
ch(r'若 \(a=\sqrt{8}+\sqrt{6}\)，\(b=\sqrt{8}-\sqrt{6}\)，則 \(a^2-b^2=\)？',[r'\(8\sqrt{2}\)',r'\(8\sqrt{3}\)',r'\(16\sqrt{2}\)',r'\(16\sqrt{3}\)'],4,r'\(a^2-b^2=(a+b)(a-b)=2\sqrt{8}\times2\sqrt{6}=4\sqrt{48}=16\sqrt{3}\)。')
ch(r'因式分解 \(49-(2x-7)^2\) 的結果為何？',[r'\(4x(x+7)\)',r'\(4x(x-7)\)',r'\(-4x(x+7)\)',r'\(-4x(x-7)\)'],4,r'原式＝\([7+(2x-7)][7-(2x-7)]=2x(14-2x)=-4x(x-7)\)。')
ch(r'如附圖，已知四邊形 \(ABCD\)、\(AEFG\) 均為正方形，且兩正方形有部分重疊，\(B\) 點在 \(\overline{EF}\) 上。若 \(\overline{BE}=3\)，則兩正方形的面積相差多少？',['6','9','12','15'],2,r'\(\triangle ABE\) 為直角三角形，\(\overline{AB}^2-\overline{AE}^2=\overline{BE}^2=9\)，即兩正方形面積相差 9。',img=(10,370,1235,520,1335))
ch(r'有一帳篷的側面如附圖，若 \(\angle ABC=90^\circ\)，\(\overline{BC}=1.2\) 公尺，\(\overline{AC}=2\) 公尺，已知支架 \(\overline{BD}\) 垂直 \(\overline{AC}\)，則 \(\overline{BD}\) 為多少公尺？',['1.2','1','0.96','0.6'],3,r'\(\overline{AB}=\sqrt{2^2-1.2^2}=1.6\)，\(\overline{BD}=\dfrac{1.6\times1.2}{2}=0.96\)（公尺）。',img=(10,815,115,1005,225))
endp()

sec('第11回 4-1 因式分解解一元二次方程式')
ch(r'請問 \(x=3\) 不是下列哪一個方程式的解？',[r'\(x^2=3x\)',r'\(x^2+2x-15=0\)',r'\(2x^2-5x-3=0\)',r'\((x-1)(x-5)=4\)'],4,r'代入 \(x=3\)：(D) \((3-1)(3-5)=-4\neq4\)。')
ch(r'已知兩數 \(a\)、\(b\)，且 \(ab=0\)，則下列何者一定正確？',[r'\(a=0\) 且 \(b\neq0\)',r'\(a\neq0\) 或 \(b\neq0\)',r'\(a=b=0\)',r'\(a=0\) 或 \(b=0\)'],4,r'兩數相乘為 0，則至少有一數為 0，即 \(a=0\) 或 \(b=0\)。')
ch('下列何者為一元二次方程式？',[r'\(2x^2-5x+7=x+2x^2\)',r'\(\dfrac{2}{3}x^2+7x-5=4\)',r'\(x^2+x+1\)',r'\((x-4)(x+5)\)'],2,r'(A) 化簡後為 \(-6x+7=0\)，一元一次方程式；(C)(D) 不是方程式。')
ch(r'若方程式 \(\left(\dfrac{x}{3}-1\right)(x+2)=0\) 的兩根為 \(a\)、\(b\)，且 \(a>b\)，則下列哪一個選項正確？',[r'\(3a=-6\)',r'\(2b=6\)',r'\(a-b=-1\)',r'\(a+b=1\)'],4,r'\(x=3\) 或 \(x=-2\)，\(a=3\)，\(b=-2\)，\(a+b=1\)。')
ch(r'小寶解一元二次方程式 \(2x^2-3x-5=6x^2-29x+35\) 的過程如下：步驟一：左右兩式分別因式分解 \(\Rightarrow(2x-5)(x+1)=(2x-5)(3x-7)\)；步驟二：左右兩式同除以 \(2x-5\)，得到 \(x+1=3x-7\)；步驟三：移項得 \(2x=8\)，所以 \(x=4\)。請從哪一個步驟開始發生錯誤？',['步驟一','步驟二','步驟三','過程完全沒有錯誤'],2,r'\(2x-5\) 可能為 0，不能同除，會漏掉 \(x=\dfrac{5}{2}\) 這個解。')
ch(r'下列何者是 \((x-1)(x-2)=12\) 的解？',['1 和 2','4 和 6','5 和 －2','5（重根）'],3,r'\(x^2-3x+2=12\Rightarrow x^2-3x-10=0\Rightarrow(x-5)(x+2)=0\)，\(x=5\) 或 \(-2\)。')
ch(r'下列哪一個方程式和 \(\dfrac{1}{3}x^2-\dfrac{1}{3}x-2=0\) 有相同的解？',[r'\(3x^2-3x-6=0\)',r'\(x^2-x-6=0\)',r'\(2x^2-2x-3=0\)',r'\(\dfrac{1}{6}x^2-\dfrac{1}{6}x-\dfrac{1}{3}=0\)'],2,r'等號兩邊同乘以 3，得 \(x^2-x-6=0\)。')
ch(r'【素養】老師在坐標平面上畫了一個點，妮妮說：「\(x\) 坐標是 \(a^2-7a-18=0\) 的正根喔！」小芸說：「\(y\) 坐標是 \(2b^2+5b-3=0\) 的負根喔！」則該點的坐標為何？',[r'\((9,-3)\)',r'\((9,-1)\)',r'\((6,-3)\)',r'\((6,-1)\)'],1,r'\((a-9)(a+2)=0\)，正根 \(a=9\)；\((2b-1)(b+3)=0\)，負根 \(b=-3\)。',img=(11,100,1190,465,1295))
ch(r'已知 \(m\) 為 \(x^2+3x+2=0\) 的解，則 \(2m^2+6m+4=\)？',['－4','－2','0','2'],3,r'\(m^2+3m+2=0\)，\(2m^2+6m+4=2(m^2+3m+2)=0\)。')
ch(r'已知方程式 \((x-5)^2-64=0\) 的解為 \(a\)、\(b\)，則 \(a\times b=\)？',['－39','－26','26','39'],1,r'\((x-5)^2=64\Rightarrow x-5=\pm8\Rightarrow x=13\) 或 \(-3\)，\(ab=-39\)。')
endp()

sec('第12回 4-2 配方法與公式解')
ch(r'欲將 \(x^2+6x\) 配成完全平方式，則應加上多少？',['4','6','9','12'],3,r'\(\left(\dfrac{6}{2}\right)^2=9\)，\(x^2+6x+9=(x+3)^2\)。')
ch(r'已知一元二次方程式 \(x^2-x-1=0\) 的兩根為 \(a\)、\(b\)，其中 \(a>b\)，則 \(a-b\) 之值為何？',['0','1',r'\(\sqrt{5}\)',r'\(2\sqrt{5}\)'],3,r'\(x=\dfrac{1\pm\sqrt{5}}{2}\)，\(a-b=\dfrac{1+\sqrt{5}}{2}-\dfrac{1-\sqrt{5}}{2}=\sqrt{5}\)。')
ch('下列哪一個一元二次方程式無解？',[r'\(x^2-x-2=0\)',r'\(2x^2+x+3=0\)',r'\(3x^2+13x+7=0\)',r'\(x^2-5x-3=0\)'],2,r'(B) 判別式＝\(1^2-4\times2\times3=-23<0\)，無解。')
ch(r'欲使 \(x^2+2x+1\) 的值為 5，則 \(x=\)？',[r'\(-1\pm\sqrt{5}\)',r'\(1\pm\sqrt{5}\)',r'\(-2\pm\sqrt{5}\)',r'\(2\pm\sqrt{5}\)'],1,r'\((x+1)^2=5\Rightarrow x+1=\pm\sqrt{5}\Rightarrow x=-1\pm\sqrt{5}\)。')
ch(r'若 \(a\) 是一元二次方程式 \(9x^2-4=0\) 的正根，\(b\) 是一元二次方程式 \(25x^2=16\) 的負根，則 \(a+b=\)？',[r'\(\dfrac{2}{15}\)',r'\(-\dfrac{2}{15}\)',r'\(\dfrac{1}{15}\)',r'\(-\dfrac{1}{15}\)'],2,r'\(a=\dfrac{2}{3}\)，\(b=-\dfrac{4}{5}\)，\(a+b=\dfrac{10}{15}-\dfrac{12}{15}=-\dfrac{2}{15}\)。')
ch(r'已知一元二次方程式 \(2x^2+6x-3=0\) 的解為 \(x=\dfrac{-3\pm\sqrt{k}}{2}\)，則 \(k=\)？',['6','11','14','15'],4,r'\(x=\dfrac{-6\pm\sqrt{36+24}}{4}=\dfrac{-6\pm2\sqrt{15}}{4}=\dfrac{-3\pm\sqrt{15}}{2}\)，\(k=15\)。')
ch(r'老師請冬冬、秋秋、小夏、阿春四人接力解方程式 \((3x-1)^2-7=1\)，其過程如下：冬冬：\((3x-1)^2=8\)；秋秋：\(3x-1=2\sqrt{2}\)；小夏：\(3x=1+2\sqrt{2}\)；阿春：\(x=\dfrac{1+2\sqrt{2}}{3}\)。老師說四人最後所得的結果有誤，則從哪一人開始發生錯誤？',['冬冬','秋秋','小夏','阿春'],2,r'\((3x-1)^2=8\Rightarrow3x-1=\pm2\sqrt{2}\)，秋秋漏掉負的平方根。',img=(12,120,895,480,1022))
ch(r'利用公式解解方程式 \(x^2-2bx+c=0\)，可得 \(x=\)？',[r'\(b\pm\sqrt{2b-c}\)',r'\(b\pm\sqrt{b-2c}\)',r'\(b\pm2\sqrt{b^2-c}\)',r'\(b\pm\sqrt{b^2-c}\)'],4,r'\(x=\dfrac{2b\pm\sqrt{4b^2-4c}}{2}=b\pm\sqrt{b^2-c}\)。')
ch(r'小睿解 \(x^2-5x-1=0\) 的過程中得到 \(x-\dfrac{5}{2}=a\)，則 \(a=\)？',['1',r'\(\dfrac{29}{4}\)',r'\(\pm\dfrac{\sqrt{29}}{2}\)',r'\(\dfrac{5\pm\sqrt{29}}{2}\)'],3,r'\(x^2-5x+\dfrac{25}{4}=1+\dfrac{25}{4}\Rightarrow\left(x-\dfrac{5}{2}\right)^2=\dfrac{29}{4}\Rightarrow x-\dfrac{5}{2}=\pm\dfrac{\sqrt{29}}{2}\)。')
ch(r'已知 \(x\) 的方程式 \(mx^2-5x+m^2-8m=0\) 有一根為 \(-1\)，則 \(m=\)？',[r'\(\dfrac{4\pm\sqrt{6}}{2}\)',r'\(\dfrac{4\pm\sqrt{26}}{2}\)',r'\(\dfrac{7\pm\sqrt{23}}{2}\)',r'\(\dfrac{7\pm\sqrt{29}}{2}\)'],4,r'\(x=-1\) 代入：\(m+5+m^2-8m=0\Rightarrow m^2-7m+5=0\Rightarrow m=\dfrac{7\pm\sqrt{49-20}}{2}=\dfrac{7\pm\sqrt{29}}{2}\)。')
endp()

sec('第13回 4-3 應用問題')
ch(r'已知甲有 \(x\) 元，乙的錢比甲少 10 元，且兩人的錢數相乘剛好是 3000，則依題意可列出下列哪一個方程式？',[r'\(x(x-10)=3000\)',r'\(x(x+10)=3000\)',r'\(x^2+(x-10)^2=3000\)',r'\((x-10)(x+10)=3000\)'],1,r'乙有 \((x-10)\) 元，\(x(x-10)=3000\)。')
ch(r'某水果商買進一箱火龍果，若每 \(x\) 顆裝一盒時恰可裝滿 \(x\) 盒，且賣掉 1 盒後，還剩下 56 顆火龍果，則該箱火龍果原本共有幾顆？',['64','81','100','121'],1,r'\(x^2-x=56\Rightarrow(x-8)(x+7)=0\Rightarrow x=8\)（負不合），共 \(8^2=64\) 顆。')
ch('可可將自己的年齡先減 5，再平方，最後減去 20，得到的數恰好是祖母的年齡 61 歲，則可可今年幾歲？',['12','13','14','15'],3,r'\((x-5)^2-20=61\Rightarrow(x-5)^2=81\Rightarrow x-5=\pm9\Rightarrow x=14\) 或 \(-4\)（不合）。')
ch('阿植在計算某正數的平方時，不小心計算成此正數的 2 倍，最後所得到的結果比正確答案少 48，則此正數為多少？',['4','6','8','10'],3,r'\(x^2-2x=48\Rightarrow(x-8)(x+6)=0\Rightarrow x=8\)（負不合）。')
ch('純純、小艾兩人一起去文具店，已知小艾所花錢數比純純所花錢數的 7 倍少 4 元。若小艾再花 64 元，則小艾所花錢數恰好為純純所花錢數的平方。請問純純、小艾兩人所花錢數相差多少元？',['64','68','72','76'],2,r'設純純花 \(x\) 元，\(7x-4+64=x^2\Rightarrow x^2-7x-60=0\Rightarrow(x-12)(x+5)=0\Rightarrow x=12\)，小艾花 80 元，相差 68 元。')
ch('【素養】老師帶了 250 顆糖果分給班上同學，若男同學每人分得顆數比女同學少 4 顆，最後剩下 16 顆。玫玫說：「男同學每人分得顆數和女同學人數相同。」小寬說：「女同學每人分得顆數和男同學人數相同。」則班上共有多少位同學？',['21','22','23','24'],2,r'設男生 \(b\) 人、女生 \(g\) 人，則男生每人分 \(g\) 顆、女生每人分 \(b\) 顆，\(g=b-4\)，\(2bg=250-16=234\Rightarrow b(b-4)=117\Rightarrow(b-13)(b+9)=0\Rightarrow b=13\)，\(g=9\)，共 22 人。',img=(13,125,948,520,1022))
ch('某次羽球聯賽預賽規定，每一隊參賽隊伍均需和其他隊伍進行一場比賽。若預賽共進行了 120 場，則共有幾隊隊伍參賽？',['13','14','15','16'],4,r'\(\dfrac{n(n-1)}{2}=120\Rightarrow n^2-n-240=0\Rightarrow(n-16)(n+15)=0\Rightarrow n=16\)。')
ch(r'已知黃金比例身材為「上半身：下半身＝下半身：全身」。若思思的身高為 150 公分，且下半身長為 90 公分，則她再穿上幾公分高的鞋子可使她的身材最接近黃金比例？（\(\sqrt{5}\approx2.23\)）',['1','3','5','7'],4,r'設鞋高 \(x\) 公分，上半身 60 公分，\(60:(90+x)=(90+x):(150+x)\Rightarrow(90+x)^2=60(150+x)\Rightarrow x^2+120x-900=0\Rightarrow x=-60+30\sqrt{5}\approx6.9\)，最接近 7。')
endp()

sec('第14回 5-1 資料整理與統計圖表①')
ch('老師想知道阿土班上這次段考英語成績不及格的人數占全班人數的比例，於是請阿土繪製統計圖，則阿土繪製下列哪一種統計圖最恰當？',['次數分配折線圖','累積次數分配折線圖','相對次數分配折線圖','累積相對次數分配折線圖'],4,r'累積相對次數分配折線圖可直接讀出「未滿 60 分」占全班的百分比。')
psg('附圖是某泡芙店記錄 120 天每日銷售量的相對次數分配直方圖（40～50 盒 10%、50～60 盒 25%、60～70 盒 45%、70～80 盒 15%、80～90 盒 5%）。')
ch('哪一組銷售量的天數最少？有幾天？',['40～50 盒，有 10 天','40～50 盒，有 12 天','80～90 盒，有 5 天','80～90 盒，有 6 天'],4,r'80～90 盒占 5% 最少，\(120\times5\%=6\)（天）。',img=(14,320,330,515,450))
ch('每日銷售量不到 60 盒的天數有幾天？',['12','35','42','54'],3,r'\(120\times(10\%+25\%)=42\)（天）。',img=(14,320,330,515,450))
psg(r'附表為某國中八年甲班學生國文分數的累積次數分配表（60～70 分：次數 2、累積 2；70～80 分：次數 7、累積 \(a\)；80～90 分：次數 \(b\)、累積 14；90～100 分：次數 \(c\)、累積 20）。')
ch(r'則 \(a=\)？',['5','7','8','9'],4,r'\(a=2+7=9\)。',img=(14,118,660,510,735))
ch('90～100 分的相對次數為何？',['30%','35%','40%','45%'],1,r'\(c=20-14=6\)，\(\dfrac{6}{20}\times100\%=30\%\)。',img=(14,118,660,510,735))
ch('在累積相對次數分配折線圖中，坐標 (50, 70) 的點所代表的意義為下列何者？',['未滿 50 者占 70%','未滿 50 者有 70 筆','恰為 50 者占 70%','恰為 50 者有 70 筆'],1,r'累積相對次數分配折線圖中，(50, 70) 表示未滿 50 的資料占全部的 70%。')
ch('附圖是某市記錄去年 8 時～20 時車禍肇事的累積次數分配折線圖，則下列敘述何者錯誤？',['14 時～16 時車禍肇事的次數最少','18 時～20 時車禍肇事的次數最多','12 時～14 時車禍肇事的次數約占總累積次數的一半',r'12 時之前（不含 12 時）車禍肇事的次數超過總累積次數的 \(\dfrac{1}{3}\)'],3,r'各時段次數：56、32、40、26、38、68。(C) 12～14 時有 40 次，遠小於 260 的一半；(D) 12 時前有 88 次，\(88>\dfrac{260}{3}\)。',img=(14,280,960,515,1075))
psg('附圖是某班學生身高的累積相對次數分配折線圖（140：0%、145：10%、150：20%、155：30%、160：70%、165：90%、170：90%、175：100%）。')
ch('則哪一組的人數最多？',['150～155 公分','155～160 公分','160～165 公分','165～170 公分'],2,r'155～160 公分占 \(70\%-30\%=40\%\)，最多。',img=(14,320,1245,515,1390))
ch('若全班有 50 人，則身高在 160～165 公分這一組的有多少人？',['6','8','10','12'],3,r'\(50\times(90\%-70\%)=10\)（人）。',img=(14,320,1245,515,1390))
endp()

sec('第15回 5-1 資料整理與統計圖表②')
ch('附圖為 400 位學生每分鐘心跳次數的相對次數分配折線圖，則每分鐘心跳次數 70～90 下的共有多少人？',['170','230','250','320'],3,r'70～90 下占 \(40\%+22.5\%=62.5\%\)，\(400\times62.5\%=250\)（人）。',img=(15,170,200,430,340))
psg(r'附表是某班學生 15 次投籃測驗結果的相對次數分配表（0～3 球：\(a\) 人、20%；4～7 球：12 人、\(b\%\)；8～11 球：9 人、30%；12～15 球：\(c\) 人、\(d\%\)）。')
ch('則該班學生共有多少人？',['25','30','35','40'],2,r'\(9\div30\%=30\)（人）。',img=(15,105,440,495,512))
ch(r'表中的 \(b=\)？',['25','30','35','40'],4,r'\(\dfrac{12}{30}\times100\%=40\%\)，\(b=40\)。',img=(15,105,440,495,512))
psg('附圖為 200 位學生某次數學測驗成績的相對次數分配直方圖，其中有部分被塗汙（40～50：5%、50～60：10%、60～70：10%、80～90：30%、90～100：25%）。')
ch('則 70～80 分這一組有多少人？',['40','50','60','70'],1,r'70～80 分占 \(100\%-5\%-10\%-10\%-30\%-25\%=20\%\)，\(200\times20\%=40\)（人）。',img=(15,320,630,500,765))
ch('未滿 90 分的學生有多少人？',['120','140','150','180'],3,r'\(200\times(100\%-25\%)=150\)（人）。',img=(15,320,630,500,765))
ch(r'已知小涵記錄某月上班日開車平均時速的相對次數分配折線圖中，共有 \(A(75,30)\)、\(B(85,40)\)、\(C(95,30)\)、\(D(105,10)\) 四個點。若 \(B\) 點的相對次數畫錯了，則正確的相對次數應為何？',['25','30','35','40'],2,r'各組相對次數總和為 100%，\(100-30-30-10=30\)。')
psg('附圖是平安診所某日 120 位病人看診時間的累積相對次數分配折線圖（5 分鐘：10%、10：25%、15：60%、20：80%、25：85%、30：90%、35：100%）。')
ch('則看診時間 0～5 分鐘的人數與下列哪一組看診時間的人數相同？',['5～10 分鐘','20～25 分鐘','25～30 分鐘','30～35 分鐘'],4,r'0～5 分鐘占 10%，30～35 分鐘占 \(100\%-90\%=10\%\)，人數相同。',img=(15,270,1040,500,1165))
ch('若桐桐是該診所當日的病人，且她進診間的時間為 15:23、出診間的時間為 15:41，則還有多少位病人的看診時間與桐桐記錄在同一組？',['21','22','23','24'],3,r'看診 18 分鐘，屬 15～20 分鐘這一組，占 \(80\%-60\%=20\%\)，共 \(120\times20\%=24\)（人），扣除桐桐還有 23 人。',img=(15,270,1040,500,1165))
endp()

sec('第16回 複習三（4-1～5-1）')
ch(r'某美術館的門票每張 150 元時，每日平均參觀人數為 400 人。經調查發現，門票每漲 1 元，每日參觀人數就減少 5 人。若門票漲 \(x\) 元後，每日門票收入為 57720 元，則依題意可列出下列哪一個方程式？【素養】',[r'\((150+x)(400-x)=57720\)',r'\((150+5x)(400-x)=57720\)',r'\((150+5x)(400-5x)=57720\)',r'\((150+x)(400-5x)=57720\)'],4,r'票價變為 \(150+x\) 元，人數減少 \(5x\) 人變為 \(400-5x\) 人，收入 \((150+x)(400-5x)=57720\)。')
ch('附圖是某公司員工薪資（萬元）的累積相對次數分配折線圖（2.5：0%、3：25%、3.5：55%、4：70%、4.5：80%、5：85%、5.5：100%），則哪一組的人數最多？',['2.5～3 萬元','3～3.5 萬元','3.5～4 萬元','4～4.5 萬元'],2,r'各組相對次數依序為 25%、30%、15%、10%、5%、15%，3～3.5 萬元占 30% 最多。',img=(16,305,420,495,578))
ch('下列哪一個式子是完全平方式？',[r'\(x^2+2x+2\)',r'\(x^2+3x-3\)',r'\(x^2-4x+4\)',r'\(x^2+5x+5\)'],3,r'\(x^2-4x+4=(x-2)^2\)。')
ch(r'關於方程式 \(3x^2-4x+5=0\) 的解，下列敘述何者正確？',['兩根相等','兩根相異','無解','無法判斷'],3,r'判別式 \((-4)^2-4\times3\times5=16-60=-44<0\)，無解。')
ch('附圖為阿正班上同學體重的相對次數分配折線圖（35：30%、45：45%、55：15%、65：10%，各點為組中點）。若體重 40～50 公斤的有 18 人，則全班共有多少人？',['30','36','40','50'],3,r'40～50 公斤占 45%，\(18\div45\%=40\)（人）。',img=(16,295,850,495,992))
ch(r'若方程式 \((2x-5)(x-4)=(x-4)(x+1)\) 的兩根為 \(a\)、\(b\)，則 \(|a-b|=\)？',['2','3','4','5'],1,r'移項得 \((x-4)[(2x-5)-(x+1)]=0\)，即 \((x-4)(x-6)=0\)，兩根為 4、6，\(|a-b|=2\)。')
ch(r'若 \(m\) 是方程式 \(x^2-2x-6=0\) 的一根，則 \(3m^2-6m=\)？',['12','18','24','30'],2,r'\(m^2-2m=6\)，\(3m^2-6m=3(m^2-2m)=18\)。')
ch('阿莉 2 年前年齡的平方恰等於她 18 年後的年齡，則阿莉今年幾歲？【素養】',['7','8','9','10'],1,r'設今年 \(x\) 歲，\((x-2)^2=x+18\)，\(x^2-5x-14=0\)，\((x-7)(x+2)=0\)，\(x=7\)（負不合）。')
